import java.util.Scanner;

public class Main {
    static final int N = 505;
    static long[] dp = new long[N], f = new long[N], d = new long[N][N], fd = new long[N][N], C = new long[N][N];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();

        int n = a;
        int m = b;
        int M = c;

        f[0] = 1;
        for (int i = 0; i <= n; ++i) {
            C[i][0] = 1;
            C[i][i] = 1;
            for (int j = 1; j < i; ++j) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % M;
            }
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= i; ++j) {
                f[i] = (f[i] + f[j - 1] * f[i - j] % M * C[i - 1][j - 1] % M * (i + 1)) % M;
                int s = 0;
                for (int k = 1; k <= i; ++k) {
                    s += Math.abs(k - j);
                }
                dp[i] = (dp[i] + dp[j - 1] * f[i - j] % M * C[i - 1][j - 1] % M * (i + 1)
                        + f[j - 1] * dp[i - j] % M * C[i - 1][j - 1] % M * (i + 1)
                        + s * f[j - 1] % M * f[i - j] % M * C[i - 1][j - 1]) % M;
            }
        }

        fd[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= Math.min(m, i); ++j) {
                fd[i][j] = fd[i - 1][j];
                d[i][j] = d[i - 1][j];
                for (int k = 1; k <= j; ++k) {
                    long prev_fd = (i - k - 1 >= 0) ? fd[i - k - 1][j - k] : 1;
                    long prev_d = (i - k - 1 >= 0) ? d[i - k - 1][j - k] : 0;
                    fd[i][j] = (fd[i][j] + (prev_fd * f[k] % M) * C[j][k]) % M;
                    d[i][j] = (d[i][j] + ((prev_fd * dp[k] + prev_d * f[k]) % M) * C[j][k]) % M;
                }
            }
        }

        System.out.println((d[n][m] % M + M) % M);
        sc.close();
    }
}

